<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Snake Game</title>
    <style>
        body {
            background-color: #121212;
            color: #ffffff;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }

        #game-container {
            text-align: center;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 15px;
        }

        #score {
            font-size: 24px;
            font-weight: bold;
            color: #00ff88;
        }

        canvas#snake {
            border: 4px solid #333;
            background-color: #1e1e1e;
            box-shadow: 0 0 20px rgba(0, 0, 0, 0.5);
            image-rendering: pixelated;
        }

        .controls {
            display: flex;
            gap: 10px;
        }

        button {
            padding: 10px 20px;
            font-size: 16px;
            cursor: pointer;
            background-color: #333;
            color: white;
            border: none;
            border-radius: 4px;
            transition: background-color 0.2s, transform 0.1s;
        }

        button:hover {
            background-color: #444;
        }

        button:active {
            transform: scale(0.95);
        }

        #start { background-color: #2e7d32; }
        #pause { background-color: #c62828; }
        #reset { background-color: #1565c0; }
    </style>
</head>
<body>

<div id="game-container">
    <div id="score">Score: 0</div>
    <canvas id="snake" width="400" height="400"></canvas>
    <div class="controls">
        <button id="start">Start</button>
        <button id="pause">Pause</button>
        <button id="reset">Reset</button>
    </div>
</div>

<script>
(function() {
    const canvas = document.getElementById('snake');
    const ctx = canvas.getContext('2d');
    const scoreEl = document.getElementById('score');

    // Configuration
    const w = 20;
    const h = 20;
    const cellSize = 400 / w;

    // Game State
    let snakeArr = [];
    let foodPos = [5, 5];
    let scoreVal = 0;
    let isAliveStatus = true;
    let currentDir = 'right';
    let nextDir = 'right';
    let intervalId = null;

    function draw() {
        // Clear canvas
        ctx.fillStyle = '#1e1e1e';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Draw Grid (subtle)
        ctx.strokeStyle = '#252525';
        ctx.lineWidth = 1;
        for (let i = 0; i <= w; i++) {
            ctx.beginPath(); ctx.moveTo(i * cellSize, 0); ctx.lineTo(i * cellSize, canvas.height); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(0, i * cellSize); ctx.lineTo(canvas.width, i * cellSize); ctx.stroke();
        }

        // Draw Food
        ctx.fillStyle = '#ff5252';
        ctx.beginPath();
        const centerX = foodPos[0] * cellSize + cellSize / 2;
        const centerY = foodPos[1] * cellSize + cellSize / 2;
        ctx.arc(centerX, centerY, cellSize / 3, 0, Math.PI * 2);
        ctx.fill();

        // Draw Snake
        snakeArr.forEach((part, index) => {
            ctx.fillStyle = (index === 0) ? '#00ff88' : '#00b35f';
            ctx.fillRect(part[0] * cellSize + 1, part[1] * cellSize + 1, cellSize - 2, cellSize - 2);
        });

        // Draw Game Over Overlay
        if (!isAliveStatus) {
            ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = '#ffffff';
            ctx.font = '30px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2);
        }
    }

    function spawnFood() {
        let newX, newY;
        let attempts = 0;
        while (attempts < 100) {
            newX = Math.floor(Math.random() * w);
            newY = Math.floor(Math.random() * h);
            // Ensure food doesn't spawn on snake body
            if (!snakeArr.some(p => p[0] === newX && p[1] === newY)) {
                foodPos = [newX, newY];
                return;
            }
            attempts++;
        }
        // Fallback if no space found (unlikely in 20x20)
        foodPos = [Math.floor(Math.random() * w), Math.floor(Math.random() * h)];
    }

    const gameApi = {
        w, h,
        reset() {
            clearInterval(intervalId);
            intervalancleId = null; // Note: this refers to local intervalId
            intervalId = null;
            snakeArr = [[5, 10], [4, 10], [3, 10]];
            foodPos = [12, 10];
            scoreVal = 0;
            isAliveStatus = true;
            currentDir = 'right';
            nextDir = 'right';
            scoreEl.innerText = `Score: ${scoreVal}`;
            draw();
        },
        tick() {
            if (!isAliveStatus) return;

            // Apply queued turn
            currentDir = nextDir;

            const head = snakeArr[0];
            let dx = 0, dy = 0;
            if (currentDir === 'up') dy = -1;
            else if (currentDir === 'down') dy = 1;
            else if (currentDir === 'left') dx = -1;
            else if (currentDir === 'right') dx = 1;

            const newHead = [head[0] + dx, head[1] + dy];

            // Check wall collision
            if (newHead[0] < 0 || newHead[0] >= w || newHead[1] < 0 || newHead[1] >= h) {
                isAliveStatus = false;
                clearInterval(intervalId);
                intervalId = null;
            } else {
                // Check self collision
                if (snakeArr.some(p => p[0] === newHead[0] && p[1] === newHead[1])) {
                    isAliveStatus = false;
                    clearInterval(intervalId);
                    intervalId = null;
                } else {
                    // Move snake
                    snakeArr.unshift(newHead);
                    // Check food collision
                    if (newHead[0] === foodPos[0] && newHead[1] === foodPos[1]) {
                        scoreVal++;
                        scoreEl.innerText = `Score: ${scoreVal}`;
                        spawnFood();
                    } else {
                        snakeArr.pop();
                    }
                }
            }
            draw();
        },
        setDir(dir) {
            const opposites = { 'up': 'down', 'down': 'up', 'left': 'right', 'right': 'left' };
            // Ignore 180 reversal relative to actual current movement
            if (opposites[dir] !== currentDir) {
                nextDir = dir;
            }
        },
        setFood(x, y) {
            foodPos = [x, y];
            draw();
        },
        snake: () => snakeArr.map(p => [...p]),
        food: () => [...foodPos],
        alive: () => isAliveStatus,
        score: () => scoreVal
    };

    // Expose API
    window.game = gameApi;

    // Controls
    document.getElementById('start').onclick = () => {
        if (!intervalId && isAliveStatus) {
            intervalId = setInterval(gameApi.tick, 150);
        } else if (!isAliveStatus) {
            gameApi.reset();
            intervalId = setInterval(gameApi.tick, 150);
        }
    };

    document.getElementById('pause').onclick = () => {
        clearInterval(intervalId);
        intervalIntId = null; // for local scope tracking
        intervalId = null;
    };

    document.getElementById('reset').onclick = () => gameApi.reset();

    window.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowUp') gameApi.setDir('up');
        else if (e.key === 'ArrowDown') gameApi.setDir('down');
        else if (e.key === 'ArrowLeft') gameApi.setDir('left');
        else if (e.key === 'ArrowRight') gameApi.setDir('right');
    });

    // Initialize
    gameApi.reset();
})();
</script>

</body>
</html>

